//! Cargo-driven `msv1_0.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is msv1_0-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "___ImageBase", Some(0x70f70000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "__ImageBase", Some(0x7fecc000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "__ImageBase", Some(0x7fecc000000u64)),
        o => panic!("msv1_0-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:pseh", "import:samsrv", "import:lsasrv", "import:advapi32", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust"],
        "x86_64" => &["body", "engine:pseh", "import:samsrv", "import:lsasrv", "import:advapi32", "import:kernel32", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["body", "engine:pseh", "import:samsrv", "import:lsasrv", "import:advapi32", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/msv1_0",
        "dll/win32/msv1_0",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_staticlib("msv1_0-rust")
        .rc("dll/win32/msv1_0/msv1_0.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/msv1_0/msv1_0.spec", "msv1_0.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/samsrv/samsrv.spec", "samsrv.dll", "samsrv")
        .delay_import_lib("dll/win32/lsasrv/lsasrv.spec", "lsasrv.dll", "lsasrv")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
